interface StrategyBadgeProps {
  typeStr: string;
  isActive?: boolean;
  isConfluence?: boolean;
  confluenceLabel?: string;
}

const StrategyBadge = ({ typeStr, isActive, isConfluence, confluenceLabel }: StrategyBadgeProps) => {
  const t = (typeStr || '').toUpperCase();
  const isLong = t.includes('LONG') || t.includes('BUY');
  const isShort = t.includes('SHORT') || t.includes('SELL');

  let icon = null;
  let stratColor = '';
  let stratBorderShadow = '';
  
  if (t.includes('EXTREME')) {
    icon = <Flame size={11} className="shrink-0 text-fuchsia-500" fill="currentColor" />;
    stratColor = 'text-fuchsia-600 dark:text-fuchsia-400';
    stratBorderShadow = 'border-fuchsia-500/50 shadow-[0_0_15px_rgba(217,70,239,0.25)]';
  } else if (t.includes('LIGHTNING')) {
    icon = <Zap size={11} className="shrink-0 text-yellow-500" fill="currentColor" />;
    stratColor = 'text-yellow-600 dark:text-yellow-400';
    stratBorderShadow = 'border-yellow-500/50 shadow-[0_0_15px_rgba(234,179,8,0.25)]';
  } else if (t.includes('MISSILE')) {
    icon = <Rocket size={11} className="shrink-0 text-orange-500" fill="currentColor" />;
    stratColor = 'text-orange-600 dark:text-orange-400';
    stratBorderShadow = 'border-orange-500/50 shadow-[0_0_15px_rgba(249,115,22,0.25)]';
  } else if (t.includes('CONFLUENCE') || t.includes('SCALP')) {
    icon = <Crosshair size={11} className="shrink-0 text-cyan-500" />;
    stratColor = 'text-cyan-600 dark:text-cyan-400';
    stratBorderShadow = 'border-cyan-500/50 shadow-[0_0_15px_rgba(6,182,212,0.25)]';
  } else if (t.includes('HIDDEN') && t.includes('DIVERGENCE')) {
    icon = <Eye size={11} className="shrink-0 text-teal-500" />;
    stratColor = 'text-teal-600 dark:text-teal-400';
    stratBorderShadow = 'border-teal-500/50 shadow-[0_0_15px_rgba(20,184,166,0.25)]';
  } else if (t.includes('DIVERGENCE')) {
    icon = <GitBranch size={11} className="shrink-0 text-violet-500" />;
    stratColor = 'text-violet-600 dark:text-violet-400';
    stratBorderShadow = 'border-violet-500/50 shadow-[0_0_15px_rgba(139,92,246,0.25)]';
  } else if (t.includes('VIRGIN') || t.includes('VCPR')) {
    icon = <Magnet size={11} className="shrink-0 text-emerald-500" />;
    stratColor = 'text-emerald-600 dark:text-emerald-400';
    stratBorderShadow = 'border-emerald-500/50 shadow-[0_0_15px_rgba(16,185,129,0.25)]';
  }

  const baseGradient = isLong
    ? 'bg-gradient-to-r from-green-500/20 to-green-500/5'
    : isShort
      ? 'bg-gradient-to-r from-red-500/20 to-red-500/5'
      : 'bg-gradient-to-r from-primary/20 to-primary/5';

  const defaultBorderShadow = isLong
    ? 'border-green-500/30 shadow-[0_0_15px_rgba(34,197,94,0.15)]'
    : isShort
      ? 'border-red-500/30 shadow-[0_0_15px_rgba(239,68,68,0.15)]'
      : 'border-primary/30';

  const dirGradient = `${baseGradient} ${stratBorderShadow || defaultBorderShadow}`;

  const dirColor = isLong ? 'text-green-600 dark:text-green-400' : isShort ? 'text-red-600 dark:text-red-400' : 'text-accent';
  
  const words = t.split(' ');
  const dirWord = words[0]; 
  const stratWord = words.slice(1).join(' ');

  return (
    <div className={`inline-flex items-center gap-1.5 px-2.5 py-1.5 rounded-lg border text-[10px] sm:text-[11px] font-mono uppercase tracking-widest font-black self-start ${dirGradient}`}>
      <span className={`w-1.5 h-1.5 rounded-full ${dirColor} bg-current shrink-0`}></span>
      <span className={dirColor}>{dirWord}</span>
      {stratWord && (
        <span className={`flex items-center gap-1 ml-0.5 ${stratColor || dirColor}`}>
          {icon}
          {stratWord}
        </span>
      )}
      {isConfluence && (
        <span className="inline-flex items-center gap-0.5 px-1.5 py-0.5 rounded bg-amber-500/20 text-amber-600 dark:text-amber-400 border border-amber-500/40 text-[8.5px] sm:text-[9px] font-mono font-black ml-1 tracking-tight shrink-0">
          🔥 {confluenceLabel || 'CONFLUENCE'}
        </span>
      )}
    </div>
  );
};

// ── CANONICAL CONFLUENCE SIGNAL EVALUATOR (VECTORBT VERIFIED) ────────────────
function isConfluenceSignal(sig: any, allSignals?: any[]): { isConfluence: boolean; confluenceType: string; label: string } {
  if (!sig) return { isConfluence: false, confluenceType: '', label: '' };
  
  // 1. Direct metadata tag from autonomous engine or TradingView payload
  let meta = sig.metadata;
  if (typeof meta === 'string') { try { meta = JSON.parse(meta); } catch(e) { meta = {}; } }
  
  if (meta && meta.is_confluence !== false && meta.is_confluence !== 'false' && (meta.is_confluence === true || meta.is_confluence === 'true' || meta.has_divergence_confluence === true || Boolean(meta.confluence_tag) || (Boolean(meta.confluence_type) && meta.confluence_type !== 'NONE' && meta.is_confluence === true))) {
    const cType = meta.confluence_type || meta.confluence_tag || 'CONFLUENCE';
    const cLabel = cType === 'MISSILE_DIV' ? 'MISSILE + DIV' :
                  (cType === 'SCALP_DIV' || cType === 'CONFLUENCE_DIV') ? 'SCALP + DIV' :
                  cType === 'LIGHTNING_TRIPLE' ? 'TRIPLE CONFL' : 'CONFLUENCE';
    return { isConfluence: true, confluenceType: cType, label: cLabel };
  }

  // 2. Direct name or trigger match
  const t = ((sig.type || '') + ' ' + (sig.trigger || '')).toUpperCase();
  if (t.includes('CONFLUENCE') || t.includes('MISSILE_DIV') || t.includes('SCALP_DIV') || t.includes('CONFLUENCE_DIV') || t.includes('LIGHTNING_TRIPLE')) {
    const cType: string = t.includes('MISSILE') ? 'MISSILE_DIV' :
                  (t.includes('SCALP') || t.includes('CONFLUENCE')) ? 'SCALP_DIV' :
                  t.includes('LIGHTNING') ? 'LIGHTNING_TRIPLE' : 'CONFLUENCE';
    const cLabel = cType === 'MISSILE_DIV' ? 'MISSILE + DIV' :
                  (cType === 'SCALP_DIV' || cType === 'CONFLUENCE_DIV') ? 'SCALP + DIV' :
                  cType === 'LIGHTNING_TRIPLE' ? 'TRIPLE CONFL' : 'CONFLUENCE';
    return { isConfluence: true, confluenceType: cType, label: cLabel };
  }

  // 3. Proximity-based Confluence matching across all signals for same clean symbol
  if (allSignals && allSignals.length > 0) {
    const cleanS = (sym: string) => (sym || '').replace(/^(NSE_DLY|NSE|MCX|NYMEX|COMEX|BINANCE|TVC|SGX):/i, '').replace(/1!$/, '').replace(/!$/, '').trim().toUpperCase();
    const sigClean = cleanS(sig.symbol);
    const isLong = t.includes('LONG') || t.includes('BUY');
    const isTrend = t.includes('MISSILE') || t.includes('SCALP') || t.includes('CONFLUENCE') || t.includes('LIGHTNING');
    
    if (isTrend && sigClean) {
      const sigTime = new Date(sig.signal_ts || sig.created_at).getTime();
      const windowMs = 60 * 60 * 1000; // 4 15-minute bars = 60 mins lookback
      
      const hasDivMatch = allSignals.some(s => {
        if (!s || s.id === sig.id) return false;
        if (cleanS(s.symbol) !== sigClean) return false;
        
        let sMeta = s.metadata;
        if (typeof sMeta === 'string') { try { sMeta = JSON.parse(sMeta); } catch(e) { sMeta = {}; } }
        const st = ((s.type || '') + ' ' + (s.trigger || '') + ' ' + (sMeta.strategy || '')).toUpperCase();
        
        const sIsLong = st.includes('LONG') || st.includes('BUY');
        if (sIsLong !== isLong) return false;
        if (!st.includes('DIVERGENCE') && !st.includes('DIV')) return false;
        
        const sTime = new Date(s.signal_ts || s.created_at).getTime();
        return Math.abs(sigTime - sTime) <= windowMs;
      });

      if (hasDivMatch) {
        const cType: string = t.includes('MISSILE') ? 'MISSILE_DIV' :
                      (t.includes('SCALP') || t.includes('CONFLUENCE')) ? 'SCALP_DIV' : 'LIGHTNING_TRIPLE';
        const cLabel = cType === 'MISSILE_DIV' ? 'MISSILE + DIV' :
                      (cType === 'SCALP_DIV' || cType === 'CONFLUENCE_DIV') ? 'SCALP + DIV' : 'TRIPLE CONFL';
        return { isConfluence: true, confluenceType: cType, label: cLabel };
      }
    }
  }

  return { isConfluence: false, confluenceType: '', label: '' };
}

