function isNYMEXSymbol(symbol?: string): boolean {
  if (!symbol) return false;
  const clean = symbol.replace(/^NYMEX:|^COMEX:|^CME:|^CBOT:|^NSE:|^TVC:/i, '').replace(/1!$/, '').toUpperCase().trim();
  const nymexList = ['CL', 'GC', 'HG', 'HO', 'NG', 'PA', 'PL', 'RB', 'SI'];
  return nymexList.includes(clean);
}

function getDecimals(symbol: string, value?: number | null): number {
  if (value == null || isNaN(value)) return 2;
  const sym = (symbol || '').toUpperCase().trim();
  const val = Number(value);
  const cleanSym = sym
    .replace(/^(NSE|BSE|MCX|NYMEX|BINANCE|BYBIT|COINBASE|KRAKEN|FX_IDC|OANDA|FXCM|INDEX|BLACKBULL|TVC|CAPITALCOM|PEPPERSTONE|EIGHTCAP):/i, '')
    .trim();

  // 1. Forex
  const forexList = ['EURUSD','GBPUSD','USDJPY','USDCHF','AUDUSD','USDCAD','NZDUSD','EURGBP','EURJPY','EURAUD','EURCHF','EURCAD','GBPJPY','GBPAUD','GBPCAD','GBPCHF','AUDJPY','AUDCAD','AUDNZD','CADJPY','USDINR','EURINR','GBPINR','JPYINR','AUDINR'];
  const isCryptoPair = ['BTCUSD','ETHUSD','SOLUSD','XRPUSD','ADAUSD','BNBUSD','DOGEUSD','LTCUSD','BCHUSD','LINKUSD','MATICUSD','AVAXUSD','DOTUSD','TRXUSD','ATOMUSD'].includes(cleanSym);
  if (!isCryptoPair && (forexList.includes(cleanSym) || (cleanSym.length === 6 && (cleanSym.endsWith('USD') || cleanSym.startsWith('EUR') || cleanSym.startsWith('GBP') || cleanSym.startsWith('USD') || cleanSym.startsWith('AUD') || cleanSym.startsWith('CAD') || cleanSym.startsWith('NZD') || cleanSym.startsWith('JPY'))))) {
    if (cleanSym.includes('JPY')) return 3;
    if (cleanSym.includes('INR')) return 4;
    return 5;
  }

  // 2. NYMEX Commodities
  if (cleanSym === 'NG1!' || cleanSym === 'SI1!') return 3;
  if (cleanSym === 'HG1!') return 4;
  if (cleanSym === 'RB1!' || cleanSym === 'HO1!') return 4;
  if (['GC1!', 'CL1!', 'PL1!', 'PA1!'].includes(cleanSym)) return 2;

  // 3. Crypto
  const cryptoList = ['BTCUSDT','ETHUSDT','BNBUSDT','SOLUSDT','XRPUSDT','DOGEUSDT','ADAUSDT','AVAXUSDT','TRXUSDT','TONUSDT','SHIBUSDT','DOTUSDT','LINKUSDT','MATICUSDT','LTCUSDT','BCHUSDT','NEARUSDT','UNIUSDT','APTUSDT','XLMUSDT','ATOMUSDT','ICPUSDT','STXUSDT','FILUSDT','ARBUSDT'];
  if (cryptoList.includes(cleanSym) || isCryptoPair || cleanSym.endsWith('USDT') || cleanSym.endsWith('BTC') || cleanSym.endsWith('ETH')) {
    if (val < 0.0001) return 8;
    if (val < 0.01) return 6;
    if (val < 1) return 4;
    if (val < 100) return 3;
    return 2;
  }

  // 4. MCX Commodities
  const mcxList = ['GOLD','GOLDM','GOLDPETAL','SILVER','SILVERM','SILVERMIC','CRUDEOIL','CRUDEOILM','NATURALGAS','NATURALGASM','COPPER','ZINC','ZINCM','ZINCMINI','NICKEL','NICKELMINI','LEAD','LEADMINI','ALUMINI','ALUMINIUM','ALUMINIUMM','COTTON','MENTHAOIL'];
  if (mcxList.includes(cleanSym) || cleanSym.startsWith('ALUMINI') || cleanSym.startsWith('ZINC')) {
    return 2;
  }

  return 2;
}

function formatPrice(v: any, symbol: string): string {
  if (v == null || v === '' || isNaN(v)) return '';
  const d = getDecimals(symbol, Number(v));
  
  const sym = (symbol || '').toUpperCase().trim();
  const cleanSym = sym
    .replace(/^(NSE|BSE|MCX|NYMEX|BINANCE|BYBIT|COINBASE|KRAKEN|FX_IDC|OANDA|FXCM|INDEX|BLACKBULL|TVC|CAPITALCOM|PEPPERSTONE|EIGHTCAP):/i, '')
    .trim();
    
  const isINR = sym.startsWith('NSE:') || sym.startsWith('BSE:') || sym.startsWith('MCX:') || MARKET_SYMBOLS.mcx.includes(cleanSym) || cleanSym.startsWith('ALUMINI') || cleanSym.startsWith('ZINC') || ['USDINR','EURINR','GBPINR','JPYINR','AUDINR'].includes(cleanSym);

  return Number(v).toLocaleString(isINR ? 'en-IN' : 'en-US', {
    minimumFractionDigits: d,
    maximumFractionDigits: d
  });
}

function getMarket(signal: Signal): string {
  let meta = signal.metadata || {};
  if (typeof meta === 'string') {
      try { meta = JSON.parse(meta); } catch(e) { meta = {}; }
  }
  
  const sym = ((signal.symbol || '').split(':').pop() || '').toUpperCase();
  const cleanSym = sym.replace(/1!$/, '').replace(/!$/, '').trim();
  
  if (MARKET_SYMBOLS.nifty.includes(cleanSym) || ['NIFTY', 'BANKNIFTY', 'FINNIFTY', 'MIDCPNIFTY', 'SENSEX', 'BANKEX', 'GIFTNIFTY'].includes(cleanSym)) return 'nifty';
  if (MARKET_SYMBOLS.mcx.includes(cleanSym) || cleanSym.startsWith('ALUMINI') || cleanSym.startsWith('ZINC')) return 'mcx';
  if (['GC1!','SI1!','CL1!','NG1!','HG1!','PL1!','PA1!','RB1!','HO1!'].includes(sym) || MARKET_SYMBOLS.nymex.includes(cleanSym)) return 'nymex';
  
  const isCryptoPair = ['BTCUSD','ETHUSD','SOLUSD','XRPUSD','ADAUSD','BNBUSD','DOGEUSD','LTCUSD','BCHUSD','LINKUSD','MATICUSD','AVAXUSD','DOTUSD','TRXUSD','ATOMUSD'].includes(sym);
  if (isCryptoPair || ['USDT', 'BTC', 'ETH'].some(sfx => sym.endsWith(sfx)) || MARKET_SYMBOLS.crypto.includes(cleanSym)) return 'crypto';
  
  if (MARKET_SYMBOLS.forex.includes(cleanSym) || MARKET_SYMBOLS.forex.includes(sym) || (sym.length === 6 && /^[A-Z]{6}$/.test(sym) && !MARKET_SYMBOLS.stocks.includes(cleanSym))) return 'forex';
  
  if (MARKET_SYMBOLS.world.includes(sym) || MARKET_SYMBOLS.world.includes(cleanSym)) return 'world';

  const exch = (signal.exchange || meta.exchange || '').toUpperCase();
  if (EXCHANGE_TAB[exch]) {
    const res = EXCHANGE_TAB[exch];
    if (res === 'nifty') {
      if (MARKET_SYMBOLS.stocks.includes(cleanSym) || !MARKET_SYMBOLS.nifty.includes(cleanSym)) return 'stocks';
    }
    return res;
  }
  
  if (MARKET_SYMBOLS.stocks.includes(cleanSym) || sym.endsWith('.NS') || sym.endsWith('.BO') || sym.endsWith('BE')) return 'stocks';
  
  return 'stocks'; // Default symbols not in the other 6 market types to Stocks
}

