  const avgLoserR = losingTradesR.length > 0 
    ? losingTradesR.reduce((sum, s) => sum + Math.abs(getExactPct(s) || 0), 0) / losingTradesR.length 
    : 0;

  const realizedRRNum = avgLoserR > 0 ? (avgWinnerR / avgLoserR) : (avgWinnerR > 0 ? 999 : 0);
  
  const winningTradesPts = tradesWithR.filter(s => resolveOutcome(s) === 'WIN' && getExactPct(s) != null);
  const losingTradesPts = tradesWithR.filter(s => resolveOutcome(s) === 'LOSS' && getExactPct(s) != null);
  
  const avgWinnerPts = winningTradesPts.length > 0 ? winningTradesPts.reduce((sum, s) => sum + (getExactPct(s) || 0), 0) / winningTradesPts.length : 0;
  const avgLoserPts = losingTradesPts.length > 0 ? losingTradesPts.reduce((sum, s) => sum + (getExactPct(s) || 0), 0) / losingTradesPts.length : 0;
  const realizedRRPtsNum = avgLoserPts > 0 ? (avgWinnerPts / avgLoserPts) : (avgWinnerPts > 0 ? 999 : 0);

  const realizedRRText = realizedRRNum === 999 ? 'MAX' : realizedRRNum.toFixed(2);
  
  const winRateDec = successRate / 100;
  const winLossAgg = winCount + lossCount;
  const lossRateDec = winLossAgg > 0 ? lossCount / winLossAgg : 0;
  
  let kellyR = null;
  if (realizedRRNum > 0 && realizedRRNum !== 999) {
    kellyR = (((winRateDec) - (lossRateDec / realizedRRNum)) * 100) * 0.5;
  } else if (realizedRRNum === 999) {
    kellyR = (winRateDec * 100) * 0.5;
  } else if (winLossAgg > 0 && realizedRRNum === 0) {
    kellyR = 0;
  }
  
  if (kellyR !== null && kellyR < 0) kellyR = 0;
  
