  const avgWinnerPctText = `+${avgWinnerR.toFixed(2)}%`;
  const avgLoserPctText = `-${avgLoserR.toFixed(2)}%`;
  const kellyText = kellyR != null ? `${kellyR > 0 ? '+' : ''}${kellyR.toFixed(1)}%` : '--';
  const bestTradeText = `${bestTradeR > 0 ? '+' : ''}${bestTradeR.toFixed(2)}%`;
  const maxDrawdownText = `-${maxDrawdown.toFixed(2)}%`;
