  // getSignalTime, getMarketCategory, now, todayClosedSignals moved to top
  const todayTradesWithPct = todayClosedSignals.filter(s => getExactPct(s) != null);
  const tWinsPctForToday = todayTradesWithPct.filter(s => resolveOutcome(s) === 'WIN');
  const tLossesPctForToday = todayTradesWithPct.filter(s => resolveOutcome(s) === 'LOSS');
  const todayGrossProfit = tWinsPctForToday.reduce((a, s) => a + Math.abs(getExactPct(s)!), 0);
  const todayGrossLoss = tLossesPctForToday.reduce((a, s) => a + Math.abs(getExactPct(s)!), 0);
  const todayPFVal = todayTradesWithPct.length === 0
    ? '---'
    : (todayGrossLoss > 0
        ? (todayGrossProfit / todayGrossLoss).toFixed(2)
        : (todayGrossProfit > 0 ? 'MAX' : '0.00')
      );
  const todayPFColorClass = todayPFVal === '---'
    ? 'text-primary'
    : (todayPFVal === 'MAX' || Number(todayPFVal) >= 1 ? 'text-success glow-success' : 'text-danger glow-danger');

  // Current Week's Statistics (timezone-aware)
  const isThisWeek = (s: Signal): boolean => {
      const now = new Date();
      const dayOfWeek = now.getDay();
      const dist = dayOfWeek === 0 ? -6 : 1 - dayOfWeek;
      
      const startOfWeek = new Date(now.getFullYear(), now.getMonth(), now.getDate());
      startOfWeek.setDate(startOfWeek.getDate() + dist);
      
      const sigTime = getSignalTime(s);
      return sigTime.getTime() >= startOfWeek.getTime();
  };

  const weeklyClosedSignalsForPF = closedSignals.filter(s => isThisWeek(s));
  const weeklyTradesWithPct = weeklyClosedSignalsForPF.filter(s => getExactPct(s) != null);
  const wWinsPct = weeklyTradesWithPct.filter(s => resolveOutcome(s) === 'WIN');
  const wLossesPct = weeklyTradesWithPct.filter(s => resolveOutcome(s) === 'LOSS');
  const weeklyGrossProfit = wWinsPct.reduce((a, s) => a + Math.abs(getExactPct(s)!), 0);
  const weeklyGrossLoss = wLossesPct.reduce((a, s) => a + Math.abs(getExactPct(s)!), 0);
  const weeklyPFVal = weeklyTradesWithPct.length === 0
    ? '---'
    : (weeklyGrossLoss > 0
        ? (weeklyGrossProfit / weeklyGrossLoss).toFixed(2)
        : (weeklyGrossProfit > 0 ? 'MAX' : '0.00')
      );
  const weeklyPFColorClass = weeklyPFVal === '---'
    ? 'text-primary'
    : (weeklyPFVal === 'MAX' || Number(weeklyPFVal) >= 1 ? 'text-success glow-success' : 'text-danger glow-danger');

  let sumMarketEdges = 0;
  ['nifty', 'mcx', 'nymex', 'crypto', 'forex', 'world'].forEach(mkt => {
      const specificWeeklyClosed = weeklyTradesWithPct.filter(s => getMarket(s) === mkt);
      if (specificWeeklyClosed.length > 0) {
          const sumPct = specificWeeklyClosed.reduce((a, s) => a + (getExactPct(s) || 0), 0);
          sumMarketEdges += (sumPct / specificWeeklyClosed.length);
      }
  });
  const weeklyGlobalEdge = sumMarketEdges !== 0 ? sumMarketEdges.toFixed(2) : null;
  const profitFactorTextValue = weeklyGlobalEdge != null ? `${Number(weeklyGlobalEdge) >= 0 ? '+' : ''}${weeklyGlobalEdge}%` : '---';

  // Weekly Calmar Ratio calculation (Cumulative Weekly Return % / Weekly Max Drawdown %)
  const weeklyChronoTrades = [...weeklyTradesWithPct].sort((a, b) => {
    const exitA = new Date(a.exit_at || a.updated_at || a.created_at || a.signal_ts || 0).getTime();
    const exitB = new Date(b.exit_at || b.updated_at || b.created_at || b.signal_ts || 0).getTime();
    if (exitA !== exitB) return exitA - exitB;
    const createdA = new Date(a.created_at || 0).getTime();
    const createdB = new Date(b.created_at || 0).getTime();
    return createdA - createdB;
  });

  let weeklyEquityCurve = 0;
  let weeklyPeakEquity = 0;
  let weeklyMaxDrawdown = 0;

