                        const totalBE = totalClosed - totalWins - totalLosses;
                        const winRatePct = totalClosed > 0 ? ((totalWins / totalClosed) * 100).toFixed(1) : '0.0';
                        const consolidatedNetPct = todaysTableSignals.reduce((acc, s) => acc + (getExactPct(s) || 0), 0);

                        let totalRealizedR = 0;
                        let validRCount = 0;
                        todaysTableSignals.forEach(s => {
                          const o = resolveOutcome(s);
                          const exact = getExactPct(s) || 0;
                          let meta = s.metadata || {};
                          if (typeof meta === 'string') { try { meta = JSON.parse(meta); } catch(e) { meta = {}; } }
                          if (o !== 'BREAKEVEN' && o !== 'CANCELLED') {
                            let stopVal = s.stop != null ? Number(s.stop) : (meta.stop != null ? Number(meta.stop) : (meta.sl != null ? Number(meta.sl) : null));
                            const entryVal = s.entry ? Number(s.entry) : null;
                            if (entryVal && !stopVal) {
                              const isLong = s.type?.toUpperCase().includes('LONG') || s.type?.toUpperCase().includes('BUY');
                              const cleanSym = (s.symbol || '').toUpperCase().replace(/^NSE:|^TVC:|^NYMEX:|^MCX:/i, '').replace(/1!$/, '').trim();
                              let defPct = 0.005;
                              if (['CL1!', 'CL', 'CRUDEOIL', 'CRUDEOILM'].includes(cleanSym)) defPct = 0.005;
                              else if (['GC1!', 'GC', 'GOLD', 'GOLDM', 'GOLDPETAL'].includes(cleanSym)) defPct = 0.003;
                              else if (['SI1!', 'SI', 'SILVER', 'SILVERM', 'SILVERMIC'].includes(cleanSym)) defPct = 0.005;
                              else if (['NG1!', 'NG', 'NATURALGAS', 'NATURALGASM'].includes(cleanSym)) defPct = 0.008;
                              else if (cleanSym.startsWith('NSE:') || ['ADANIENT', 'RELIANCE', 'SBIN', 'NIFTY'].includes(cleanSym)) defPct = 0.0035;
                              else if (cleanSym.endsWith('USDT') || cleanSym.endsWith('BTC')) defPct = 0.0075;
                              else if (cleanSym.length === 6) defPct = 0.0025;
                              stopVal = isLong ? entryVal * (1 - defPct) : entryVal * (1 + defPct);
                            }
                            if (entryVal && stopVal) {
                              const riskAmt = Math.abs(entryVal - stopVal);
                              if (riskAmt > 0 && exact !== 0) {
                                const realizedRewardAmt = (Math.abs(exact) / 100) * entryVal;
                                const sign = exact > 0 ? 1 : -1;
                                totalRealizedR += (sign * realizedRewardAmt / riskAmt);
                                validRCount++;
                              }
                            }
                          }
                        });
                        const consolidatedR = validRCount > 0 ? `${totalRealizedR >= 0 ? '+' : ''}${totalRealizedR.toFixed(2)}R` : '--';
                        // ── Metrics for 8-Card Metric Grid ──
                        const tWinsList = todaysTableSignals.filter(s => resolveOutcome(s) === 'WIN');
                        const tLossesList = todaysTableSignals.filter(s => resolveOutcome(s) === 'LOSS');
                        const tBECount = totalClosed - tWinsList.length - tLossesList.length;
                        const tWinRateStr = totalClosed > 0 ? ((tWinsList.length / totalClosed) * 100).toFixed(1) : '0.0';

