                        const tCalmar = totalClosed === 0 ? '0.00' : (tMaxDD > 0 ? (tSumPct / tMaxDD).toFixed(2) : (tSumPct > 0 ? 'MAX' : '0.00'));

                        const tWinProb = totalClosed > 0 ? tWinsList.length / totalClosed : 0;
                        const tAvgWin = tWinsList.length > 0 ? tGrossProfit / tWinsList.length : 0;
                        const tAvgLoss = tLossesList.length > 0 ? tGrossLoss / tLossesList.length : 0;
                        const tRR = tAvgLoss > 0 ? tAvgWin / tAvgLoss : 0;
                        const tKelly = tRR > 0 ? (((tWinProb * tRR) - (1 - tWinProb)) / tRR) * 50 : null;

