                          const tStdDev = Math.sqrt(tVariance);
                          const tDownVariance = tReturns.reduce((acc, r) => acc + Math.pow(Math.min(0, r), 2), 0) / totalClosed;
                          const tDownStdDev = Math.sqrt(tDownVariance);

