                                    <path
                                      d={dhanPaperStats.pathData}
                                      fill="none"
                                      stroke={(dhanPaperStats.totalPnL || 0) >= 0 ? '#10b981' : '#f43f5e'}
                                      strokeWidth="2.5"
                                      strokeLinecap="round"
                                      strokeLinejoin="round"
                                      className="transition-all duration-300 drop-shadow-md"
                                    />

